INSERT INTO public.recipes (id, nom, description, saison, mois, mois_numero, semaine, jour, tag, categorie, theme_special, portions, estimated_time, difficulty, image_url, ingredients, instructions, astuce, cuisson_micro_ondes, sans_four, source, source_pdf, source_page, dietary_tags, main_ingredients, equipment, canonical_ingredients_status)
VALUES
  ('city-cafe-banh-mi-poulet', 'Bánh mì au poulet', 'Baguette croustillante garnie de poulet mariné, de carotte vinaigrée, de concombre, de coriandre et d’une mayonnaise légèrement pimentée.', 'été', 'juillet', 7, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/32961655/pexels-photo-32961655.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Baguette","quantity":"2","unit":"petites","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Poulet","quantity":"240","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Carottes","quantity":"100","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Concombres","quantity":"80","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Coriandre","quantity":"10","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Mayonnaise","quantity":"2","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sauce soja","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Vinaigre","quantity":"2","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sucre","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Piment","quantity":"1","unit":"pincée","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Râper les carottes. Mélanger le vinaigre, le sucre et 2 cuillères à soupe d’eau, ajouter les carottes et laisser mariner 20 minutes.","Couper le poulet en fines lanières, le mélanger à la sauce soja puis le saisir dans une poêle chaude 6 à 8 minutes jusqu’à cuisson complète.","Mélanger la mayonnaise avec le piment. Ouvrir les baguettes sans les séparer complètement et les toaster 2 minutes.","Tartiner les baguettes de mayonnaise, garnir de poulet, carottes égouttées, concombre en rubans et coriandre. Servir aussitôt."]'::jsonb, 'Les carottes marinées se préparent la veille et se gardent jusqu’à 3 jours au réfrigérateur.', false, true, 'broco-chou', null, null, array['volaille']::text[], array['poulet', 'carottes', 'concombre']::text[], array['poêle', 'râpe', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-bagel-feta-grenade-courgette-kebab', 'Bagel au bœuf façon kebab, feta, grenade et courgette', 'Une interprétation du Berliner : bœuf épicé façon kebab, courgette grillée, feta et graines de grenade dans un bagel.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'facile', 'https://images.pexels.com/photos/38337105/pexels-photo-38337105.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Bagel","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Bœuf","quantity":"220","unit":"g émincé","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Courgettes","quantity":"120","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Feta","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Grenade","quantity":"0.5","unit":"fruit","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Yaourt","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Cumin","quantity":"0.5","unit":"c. à café","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Paprika","quantity":"0.5","unit":"c. à café","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Mélanger le yaourt avec la moitié du cumin, une pincée de paprika et du sel pour obtenir une sauce.","Couper la courgette en rubans et la saisir dans l’huile 3 à 4 minutes; réserver. Assaisonner le bœuf avec le reste du cumin et du paprika.","Faire dorer le bœuf à feu vif 3 à 5 minutes selon l’épaisseur, jusqu’à cuisson souhaitée.","Toaster les bagels. Les garnir de sauce au yaourt, courgette, bœuf, feta émiettée et graines de grenade."]'::jsonb, 'Le menu ne précise pas l’animal du kebab; cette version domestique utilise du bœuf émincé. On peut acheter des lamelles de kebab de bœuf déjà assaisonnées.', false, true, 'broco-chou', null, null, array['protéines']::text[], array['bœuf', 'feta', 'grenade', 'courgette']::text[], array['poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-croque-poulet-pesto-persil', 'Croque au poulet et pesto de persil', 'Pain de mie doré garni de poulet, emmental fondant et pesto maison au persil.', 'printemps', 'avril', 4, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'facile', 'https://images.pexels.com/photos/37228248/pexels-photo-37228248.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pain","quantity":"4","unit":"tranches épaisses","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Poulet","quantity":"160","unit":"g cuit","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Emmental","quantity":"80","unit":"g râpé","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Persil","quantity":"20","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Parmesan","quantity":"20","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Ail","quantity":"1","unit":"gousse","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"2","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Beurre","quantity":"10","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"}]'::jsonb, '["Mixer le persil, le parmesan, l’ail et l’huile d’olive jusqu’à obtenir un pesto épais. Ajouter une cuillère d’eau si nécessaire.","Préchauffer le four à 200 °C. Effilocher le poulet cuit et le mélanger avec la moitié du pesto.","Garnir deux tranches de pain de poulet et d’emmental, refermer avec le reste du pain puis beurrer légèrement l’extérieur.","Faire dorer les croques dans une poêle 2 minutes par face, puis les enfourner 6 à 8 minutes jusqu’à ce que le fromage soit fondu. Servir avec le reste du pesto."]'::jsonb, 'Un reste de poulet rôti convient très bien et réduit la préparation à 15 minutes.', false, false, 'broco-chou', null, null, array['volaille']::text[], array['poulet', 'persil', 'emmental']::text[], array['four', 'poêle', 'mixeur', 'couteau']::text[], 'verified'),
  ('city-cafe-bagel-boeuf-avocat', 'Bagel au bœuf et à l’avocat', 'Bagel garni de bœuf grillé, avocat mûr et fromage frais citronné.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 20, 'facile', 'https://images.pexels.com/photos/27135846/pexels-photo-27135846.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Bagel","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Bœuf","quantity":"220","unit":"g steak","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Avocats","quantity":"1","unit":"mûr","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Fromage frais","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Salade","quantity":"30","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Assaisonner le steak et le saisir dans une poêle huilée 2 à 4 minutes par face selon l’épaisseur et la cuisson désirée. Le laisser reposer 5 minutes.","Écraser l’avocat avec le jus de citron et une pincée de sel. Détendre le fromage frais avec une cuillère à café d’eau.","Trancher finement le bœuf reposé. Toaster les bagels côté mie.","Tartiner les bases de fromage frais, ajouter la salade, l’avocat et le bœuf, puis refermer."]'::jsonb, 'Pour une version plus tendre, choisir une bavette ou un faux-filet et trancher la viande perpendiculairement aux fibres.', false, true, 'broco-chou', null, null, array['protéines']::text[], array['bœuf', 'avocat', 'bagel']::text[], array['poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-panini-saumon-chevre-epinards', 'Panini au saumon, chèvre frais et épinards', 'Panini croustillant garni de saumon cuit, chèvre frais et jeunes épinards.', 'printemps', 'avril', 4, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'facile', 'https://images.pexels.com/photos/1885578/pexels-photo-1885578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pain","quantity":"2","unit":"pains panini","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Saumon","quantity":"200","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Chèvre","quantity":"80","unit":"g frais","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Épinards","quantity":"40","unit":"g jeunes pousses","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Chauffer une poêle-gril ou un appareil à panini. Badigeonner le saumon d’un peu d’huile et le cuire 3 à 4 minutes par face, jusqu’à ce qu’il soit opaque; l’émietter.","Ouvrir les pains. Répartir le chèvre, les épinards et le saumon, puis ajouter quelques gouttes de citron.","Refermer et griller 3 à 5 minutes dans l’appareil à panini, en pressant légèrement, jusqu’à ce que le pain soit croustillant.","Couper en deux et servir immédiatement."]'::jsonb, 'Le saumon fumé peut remplacer le filet cuit; l’ajouter après la cuisson du pain pour préserver sa texture.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['saumon', 'chèvre frais', 'épinards']::text[], array['appareil à panini ou poêle-gril', 'spatule', 'couteau']::text[], 'verified'),
  ('city-cafe-bagel-rosette-tartare', 'Bagel à la rosette et sauce tartare', 'Rosette en fines tranches, salade croquante et sauce tartare aux cornichons et câpres dans un bagel toasté.', 'printemps', 'avril', 4, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 20, 'facile', 'https://images.pexels.com/photos/23884572/pexels-photo-23884572.png?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Bagel","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Rosette","quantity":"100","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Mayonnaise","quantity":"50","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Cornichons","quantity":"20","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Câpres","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Persil","quantity":"5","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Salade","quantity":"30","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"}]'::jsonb, '["Hacher finement les cornichons, les câpres et le persil. Mélanger à la mayonnaise avec une cuillère à café de jus de citron.","Couper la rosette en tranches fines et laver puis essorer la salade.","Toaster les bagels ouverts. Étaler la sauce tartare sur les deux faces intérieures.","Garnir de salade et de rosette, refermer et servir aussitôt."]'::jsonb, 'La sauce tartare se prépare la veille et se conserve au frais dans un récipient fermé pendant 2 jours.', false, true, 'broco-chou', null, null, array['porc']::text[], array['rosette', 'bagel', 'sauce tartare']::text[], array['couteau', 'planche à découper', 'saladier']::text[], 'verified'),
  ('city-cafe-bagel-roastbeef-tartare', 'Bagel au roast-beef et sauce tartare', 'Tranches de roast-beef, salade et sauce tartare relevée de câpres dans un bagel toasté.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 20, 'facile', 'https://images.pexels.com/photos/12918205/pexels-photo-12918205.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Bagel","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Bœuf","quantity":"140","unit":"g roast-beef tranché","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Mayonnaise","quantity":"50","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Cornichons","quantity":"20","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Câpres","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Persil","quantity":"5","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Moutarde","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Salade","quantity":"30","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"}]'::jsonb, '["Hacher les cornichons, les câpres et le persil. Mélanger avec la mayonnaise et la moutarde.","Laver et essorer la salade. Toaster les bagels ouverts.","Étaler la sauce tartare sur les faces intérieures, ajouter la salade puis les tranches de roast-beef.","Refermer les bagels, couper en deux et servir froid ou à température ambiante."]'::jsonb, 'Utiliser du roast-beef froid déjà cuit du boucher; garder la sauce séparée si le sandwich est préparé à l’avance.', false, true, 'broco-chou', null, null, array['protéines']::text[], array['roast-beef', 'bagel', 'sauce tartare']::text[], array['couteau', 'planche à découper', 'saladier']::text[], 'verified'),
  ('city-cafe-panini-saumon-fromage-frais-avocat', 'Panini au saumon, fromage frais et avocat', 'Panini grillé au saumon fumé, fromage frais citronné et avocat fondant.', 'été', 'juillet', 7, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 20, 'facile', 'https://images.pexels.com/photos/6896523/pexels-photo-6896523.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pain","quantity":"2","unit":"pains panini","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Saumon fumé","quantity":"100","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Fromage frais","quantity":"80","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Avocats","quantity":"1","unit":"mûr","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Aneth","quantity":"3","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Écraser le fromage frais avec le zeste et une cuillère à café de jus de citron, puis incorporer l’aneth ciselé.","Trancher l’avocat et le citronner. Ouvrir les pains et les tartiner de fromage frais.","Garnir de saumon fumé et d’avocat, refermer et griller 3 à 4 minutes dans un appareil à panini chaud.","Servir dès que le pain est doré et croustillant."]'::jsonb, 'Pour éviter que l’avocat brunisse, le citronner juste après l’avoir tranché.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['saumon fumé', 'fromage frais', 'avocat']::text[], array['appareil à panini ou poêle-gril', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-bagel-jambon-cheddar-galette-pomme-terre', 'Bagel jambon, cheddar et galette de pomme de terre', 'Le Windsor associe jambon, cheddar fondu et petite galette de pomme de terre croustillante dans un bagel toasté.', 'hiver', 'janvier', 1, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'facile', 'https://images.pexels.com/photos/39174660/pexels-photo-39174660.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Bagel","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Jambon","quantity":"2","unit":"tranches","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Cheddar","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Pommes de terre","quantity":"250","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Œufs","quantity":"1","unit":"pièce","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Farine","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Huile","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Râper les pommes de terre et les presser dans un torchon propre pour retirer l’excès d’eau. Mélanger avec l’œuf, la farine, sel et poivre.","Former deux galettes et les cuire dans l’huile à feu moyen 4 à 5 minutes par face jusqu’à ce qu’elles soient dorées et cuites à cœur.","Ouvrir les bagels, déposer le cheddar et le jambon puis réchauffer 3 minutes au four à 200 °C ou sous un couvercle dans une poêle.","Glisser une galette chaude dans chaque bagel et servir immédiatement."]'::jsonb, 'Des rösti surgelés déjà cuits peuvent remplacer les galettes maison; les réchauffer jusqu’à ce qu’elles soient croustillantes.', false, false, 'broco-chou', null, null, array['porc']::text[], array['jambon', 'cheddar', 'pommes de terre']::text[], array['râpe', 'poêle', 'spatule', 'four']::text[], 'verified'),
  ('city-cafe-hirata-saumon-legumes-wok', 'Pain Hirata au saumon et légumes sautés', 'Pain Hirata vapeur garni de saumon laqué au soja et de légumes sautés au wok. Les pains Hirata sont des pains vapeur souples, généralement servis ouverts et garnis.', 'printemps', 'mai', 5, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'facile', 'https://images.pexels.com/photos/14987815/pexels-photo-14987815.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pain","quantity":"4","unit":"pains Hirata surgelés","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Saumon","quantity":"240","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Carottes","quantity":"100","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Chou rouge","quantity":"100","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Sauce soja","quantity":"2","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Gingembre","quantity":"10","unit":"g frais","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Miel","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sésame","quantity":"1","unit":"c. à café","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Huile","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Cuire les pains Hirata à la vapeur selon les indications du paquet, généralement 6 à 8 minutes; les garder couverts.","Couper le saumon en cubes. Le faire dorer dans une poêle avec le miel et une cuillère à soupe de sauce soja 4 à 5 minutes; réserver.","Tailler la carotte et le chou en fines lamelles. Les saisir au wok avec l’huile, le gingembre râpé et le reste de sauce soja pendant 3 minutes pour les garder croquants.","Ouvrir délicatement les pains vapeur, les garnir de légumes puis de saumon. Parsemer de sésame et servir chaud."]'::jsonb, 'Les pains Hirata sont vendus surgelés dans les épiceries asiatiques; les bao buns ouverts conviennent aussi. Ne pas les laisser sécher après cuisson vapeur.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['saumon', 'carottes', 'chou rouge']::text[], array['panier vapeur', 'wok ou grande poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-bagel-jambon-gruyere', 'Bagel au jambon et au gruyère', 'Un bagel simple et généreux au jambon, gruyère râpé et salade croquante.', 'printemps', 'mai', 5, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 15, 'très facile', 'https://images.pexels.com/photos/6492/food-breakfast-fork-bagel.jpg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Bagel","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Jambon","quantity":"2","unit":"tranches","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Gruyère","quantity":"60","unit":"g râpé","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Salade","quantity":"30","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Moutarde","quantity":"2","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Beurre","quantity":"10","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"}]'::jsonb, '["Couper les bagels en deux et les toaster côté mie.","Tartiner les bases d’un peu de beurre et de moutarde.","Ajouter la salade, le jambon et le gruyère râpé, puis refermer les bagels.","Servir froid ou passer 2 minutes sous le gril pour faire fondre légèrement le fromage."]'::jsonb, 'Le gruyère peut être remplacé par l’emmental déjà râpé si c’est ce que vous avez sous la main.', false, true, 'broco-chou', null, null, array['porc']::text[], array['jambon', 'gruyère', 'bagel']::text[], array['grille-pain ou four', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-fish-burger', 'Fish burger croustillant et sauce tartare', 'Filet de poisson pané au panko, salade fraîche et sauce tartare dans un pain burger moelleux.', 'été', 'juillet', 7, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'facile', 'https://images.pexels.com/photos/39042551/pexels-photo-39042551.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pain","quantity":"2","unit":"pains burger","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Poisson blanc","quantity":"2","unit":"filets de 140 g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Panko","quantity":"60","unit":"g","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Farine","quantity":"30","unit":"g","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Œufs","quantity":"1","unit":"pièce","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Mayonnaise","quantity":"60","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Cornichons","quantity":"20","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Câpres","quantity":"1","unit":"c. à café","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Salade","quantity":"30","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Citrons","quantity":"0.5","unit":"pièce","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile","quantity":"3","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Hacher les cornichons et les câpres, puis les mélanger à la mayonnaise avec un peu de jus de citron.","Sécher le poisson et le passer successivement dans la farine, l’œuf battu puis le panko en pressant pour faire adhérer la chapelure.","Faire chauffer l’huile dans une poêle. Cuire les filets 3 à 4 minutes par face jusqu’à ce que la panure soit dorée et le poisson opaque; égoutter sur du papier absorbant.","Toaster les pains, étaler la sauce tartare, ajouter la salade et le poisson. Servir avec le reste de sauce."]'::jsonb, 'Le cabillaud, le lieu ou le colin conviennent; adapter la cuisson à l’épaisseur et vérifier que le poisson est opaque à cœur.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['poisson blanc', 'panko', 'sauce tartare']::text[], array['poêle', 'trois assiettes creuses', 'spatule', 'couteau']::text[], 'verified')
